gvD(){return"\u041d\u0435 \u0437\u0430\u0434\u0430\u043d"},
gvw(){return"\u0421\u0435\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u043a\u043b\u044e\u0447 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0442\u044c (\u0438\u043b\u0438 \u0443\u0431\u0438\u0440\u0430\u0442\u044c) \u0442\u0440\u0435\u043a\u0438 \u0438\u0437 \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u044f\u043c\u043e \u043d\u0430 Last.fm."},
gvt(){return"\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
gvv(){return"\u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
gpi(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
