gtC(){return"\u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0441\u0435\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u043a\u043b\u044e\u0447 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \xab\u0410\u043a\u043a\u0430\u0443\u043d\u0442\xbb, \u0447\u0442\u043e\u0431\u044b \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u044c"},
gr1(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
gqq(){return"\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435"},
gA5(){return"\u041c\u043e\u0438 \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u044b\u0435"},
gA6(){return"\u041f\u043e\u0438\u0441\u043a \u0442\u0440\u0435\u043a\u0430 \u0438\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044f"},
gzS(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u0430 \u043d\u0435\u0442. \u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u0435\u0440\u0434\u0446\u0435 \u0443 \u0442\u0440\u0435\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0433\u043e."},
gr4(){return"\u041d\u0435\u0434\u0430\u0432\u043d\u0438\u0435"},
gr3(){return"\u0421\u0442\u0430\u0440\u044b\u0435"},
gr2(){return"\u0418\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c \u0410-\u042f"},
